  const dir = [Math.cos(a), 0, Math.sin(a)], side = [-Math.sin(a), 0, Math.cos(a)], base = [dir[0] * r, 0, dir[2] * r];
  const p0 = addpoint(0, add(base, mul(side, -w / 2))), p1 = addpoint(0, add(base, mul(side, w / 2)));
  const p2 = addpoint(0, add(base, [dir[0] * lean, h, dir[2] * lean]));
  const pr = addprim(0, 'poly', [p0, p1, p2]);
  setprimattrib(0, 'variant_id', pr, v);
  setprimattrib(0, 'tint', pr, 0.75 + 0.45 * rand(s, 5));
